create or replace function apply_schedule_repair_suggestion_v1(p_suggestion_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare s schedule_repair_suggestions%rowtype;b record;a record;begin perform open_permission_context('schedule.generate');select * into s from schedule_repair_suggestions where id=p_suggestion_id;if not found then raise exception 'SUGGESTION_NOT_FOUND';end if;perform assert_schedule_scenario_tenant_phase3_v1(s.scenario_id);if not s.legal_safe or s.hard_rule_impact then raise exception 'SUGGESTION_NOT_SAFE';end if;if s.action_code='MANUAL_REVIEW' then return jsonb_build_object('status','MANUAL_REQUIRED','scenario_id',s.scenario_id);end if;if s.action_code<>'REBALANCE_DAILY_LOAD' then return jsonb_build_object('status','SETTINGS_REQUIRED','action_code',s.action_code,'scenario_id',s.scenario_id);end if;select score,unplaced_count into b from schedule_scenario_status_v2 where scenario_id=s.scenario_id;perform repair_schedule_scenario_v2(s.scenario_id);perform rescore_schedule_scenario_v2(s.scenario_id);update schedule_repair_suggestions set applied_at=now() where id=s.id;perform refresh_schedule_repair_suggestions_v1(s.scenario_id);select score,unplaced_count into a from schedule_scenario_status_v2 where scenario_id=s.scenario_id;return jsonb_build_object('status','APPLIED','scenario_id',s.scenario_id,'before_score',b.score,'after_score',a.score,'before_unplaced',b.unplaced_count,'after_unplaced',a.unplaced_count);end$$;